from typing import Optional

from robot.libraries.BuiltIn import BuiltIn, RobotNotRunningError

from .utils.logger import logger


class reporting_portal:
    """
    API for reporting_portal interface.
    It allows to use reporting_portal keywords in Python keywords, outside of Robot.
    Works only during Robot Framework suite execution.
    """

    def __init__(self):
        self._check_if_executed_in_robot_context()
        BuiltIn().import_library("taf.sw.reporting_portal")

    def _check_if_executed_in_robot_context(self):
        try:
            BuiltIn()
        except RobotNotRunningError:
            logger.warning("Running keywords outside of Robot Framework.")
            raise

    def report_pm_counter(self, id: str, value: int, result: str) -> None:
        """Keyword to report PM counter result.

        :param string  id:       PM Counter ID
        :param integer value:    PM Counter value
        :param string  result:   PM Counter result. Supported values: Passed, Failed.

        :note: PM counters are not reported immediately.
               PM counters will be read by ute_reporting_portal script and will be added to robot report.
        """
        BuiltIn().run_keyword("report pm counter", id, value, result)

    def report_enb_hardware_configuration(self, configuration: str) -> None:
        """Keyword to report eNB configuration.

        :param string configuration: eNB configuration.

        :note: eNB configuration is not reported immediately.
               eNB configuration will be read by ute_reporting_portal script and will be added to robot report.
        """
        BuiltIn().run_keyword("report enb hardware configuration", configuration)

    def log_to_reporting_portal(self, message: str) -> None:
        """Keyword to log additional information for keyword.

        :param string message: eNB configuration.

        :note: additional information is not reported immediately.
               additional information will be read by ute_reporting_portal script and will be added to robot report.
        """
        BuiltIn().run_keyword("log to reporting portal", message)

    def backup_config(
            self,
            product_type: Optional[str] = None,
            load_prefix: Optional[str] = None,
            log_level: Optional[str] = None
    ) -> None:
        """Keyword to run backup action for reporting portal.

        :param string product_type: Type of product ['wmp', 'dcm']
        :param string load_prefix:  Prefix for the location
        :param string log_level:    Set if 'debug' level needed instead of 'info'

        :note: additional information is not reported immediately.
               additional information will be read by ute_reporting_portal script and will be added to robot report.
        """
        BuiltIn().run_keyword("backup config", product_type, load_prefix, log_level)

    def set_tool(self, tool_name: Optional[str] = "Robot") -> None:
        """Keyword used for setting name of tool used in test suite.

        :param string tool_name: Name of tool

        :note: additional information is not reported immediately.
               additional information will be read by ute_reporting_portal script and will be added to robot report.
        """
        BuiltIn().run_keyword("set tool", tool_name)

    def report_kpi_results(
            self,
            target: str,
            name: str,
            visible_to_db: str,
            value: str,
            kpi_type: str,
            description: str,
            category: str,
            unit: str,
    ) -> None:
        """Keyword to report kpi results.

        :param string  target:          KPI target
        :param string  name:            KPI name
        :param string  visible_to_db:   defines visibility for db
        :param string  value:           KPI value
        :param string  kpi_type:        KPI type
        :param string  description:     KPI description
        :param string  category:        KPI category
        :param string  unit:            KPI unit

        :note: KPI results are not reported immediately.
               KPI results will be read by ute_reporting_portal script and will be added to robot report.
        """
        BuiltIn().run_keyword(
            "report kpi results",
            target,
            name,
            visible_to_db,
            value,
            kpi_type,
            description,
            category,
            unit,
        )

    def add_to_test_data(
            self,
            target: str,
            name: str,
            visible_to_db: str,
            value: str,
            kpi_type: str,
            description: str,
            category: str,
            unit: str,
    ) -> None:
        """Keyword to report kpi results.

        :note: KPI results are not reported immediately.
               KPI results will be read by ute_reporting_portal script and will be added to robot report.
        """
        BuiltIn().run_keyword(
            "add to test data",
            target,
            name,
            visible_to_db,
            value,
            kpi_type,
            description,
            category,
            unit,
        )

    def map_testcase(self, testcase_name: str) -> None:
        """Keyword to map testcase name as other one.

        :param string  testcase_name:          Testcase name to be set in QC report

        :note: Testcase name is not set immediately.
               Testcase name will be read by ute_reporting_portal script and will be added to robot report.
        """
        BuiltIn().run_keyword("map testcase", testcase_name)

    def set_sw_build(self, sw_build: str) -> None:
        """Keyword to set sw build for the testcase.

        :param string  sw_build:          Testcase name to be set in QC report

        :note: sw_build is not set immediately.
               sw_build will be read by ute_reporting_portal script and will be added to robot report.
        """
        BuiltIn().run_keyword("set sw build", sw_build)

    def set_ap_build(self, ap_build: str) -> None:
        """Keyword to set sw build for the testcase.

        :param string  ap_build:          Testcase name to be set in QC report

        :note: sw_build is not set immediately.
               sw_build will be read by ute_reporting_portal script and will be added to robot report.
        """
        BuiltIn().run_keyword("set ap build", ap_build)

    def set_rtg_build(self, rtg_build: str) -> None:
        """Keyword to set sw build for the testcase.

        :param string  rtg_build:          Testcase name to be set in QC report

        :note: sw_build is not set immediately.
               sw_build will be read by ute_reporting_portal script and will be added to robot report.
        """
        BuiltIn().run_keyword("set rtg build", rtg_build)

    def set_qc_config_path(self, qc_config_path: str) -> None:
        """Keyword used for setting name of tool used in test suite.

        :param string qc_config_path:

        :note: additional information is not reported immediately.
               additional information will be read by ute_reporting_portal script and will be added to robot report.
        """
        BuiltIn().run_keyword("set qc config path", qc_config_path)

    def report_to_rp(self, name: str, result: str, ca: str, build: str, **params) -> None:
        """Keyword used for sending single report to Reporting Portal.

        :param string        name:            Keyword name
        :param string        result:          Result of keyword
        :param string        ca:              Competence Area
        :param string        build:           Build name
        :param keywords      params:          Additional parameters to be set in report (see documentation below)

        **PARAMETERS DOC:**

        +-----------------------------+-------------+
        |               **suite_data**              |
        +=============================+=============+
        | **tool**                    |   string    |
        +-----------------------------+-------------+
        | **result**                  |   string    |
        +-----------------------------+-------------+
        | **endtime**                 |   string    |
        +-----------------------------+-------------+
        | **doc**                     |   string    |
        +-----------------------------+-------------+
        | **testline**                |   string    |
        +-----------------------------+-------------+
        | **ute_version**             |   string    |
        +-----------------------------+-------------+
        | **label**                   |   string    |
        +-----------------------------+-------------+
        | **starttime**               |   string    |
        +-----------------------------+-------------+
        | **ca**                      |   string    |
        +-----------------------------+-------------+

        +-----------------------------+-------------+
        |               **test_data**               |
        +=============================+=============+
        | **suite_path**              |   string    |
        +-----------------------------+-------------+
        | **name**                    |   string    |
        +-----------------------------+-------------+
        | **username**                |   string    |
        +-----------------------------+-------------+
        | **source_control_revision** |   string    |
        +-----------------------------+-------------+
        | **doc**                     |   string    |
        +-----------------------------+-------------+
        | **starttime**               |   string    |
        +-----------------------------+-------------+
        | **endtime**                 |   string    |
        +-----------------------------+-------------+
        | **result**                  |   string    |
        +-----------------------------+-------------+
        | **fail_message**            |   string    |
        +-----------------------------+-------------+
        | **steps**                   |    list     |
        +-----------------------------+-------------+
        | **phase**                   |   string    |
        +-----------------------------+-------------+
        | **ca**                      |   string    |
        +-----------------------------+-------------+
        | **build**                   |   string    |
        +-----------------------------+-------------+
        | **build_tag**               |   string    |
        +-----------------------------+-------------+
        | **enb_nsa_build**           |   string    |
        +-----------------------------+-------------+
        | **gnb_nsa_build**           |   string    |
        +-----------------------------+-------------+
        | **cu_build**                |   string    |
        +-----------------------------+-------------+
        | **gnb_rf_shared_build**     |   string    |
        +-----------------------------+-------------+
        | **enb_rf_shared_build**     |   string    |
        +-----------------------------+-------------+
        | **bts2g_rf_shared_build**   |   string    |
        +-----------------------------+-------------+
        | **nb_rf_shared_build**      |   string    |
        +-----------------------------+-------------+
        | **parameters2**             |   string    |
        +-----------------------------+-------------+
        | **add_info**                |   string    |
        +-----------------------------+-------------+
        | **links**                   |   string    |
        +-----------------------------+-------------+
        | **iphy**                    |   string    |
        +-----------------------------+-------------+
        | **kpi_results**             |    list     |
        +-----------------------------+-------------+
        | **qc_id**                   |   integer   |
        +-----------------------------+-------------+
        | **qc_testlab_path**         |   string    |
        +-----------------------------+-------------+
        | **qc_test_set_name**        |   string    |
        +-----------------------------+-------------+
        | **qc_test_instance_name**   |   string    |
        +-----------------------------+-------------+
        | **qc_domain**               |   string    |
        +-----------------------------+-------------+
        | **qc_project**              |   string    |
        +-----------------------------+-------------+
        | **counter_results**         |    list     |
        +-----------------------------+-------------+
        | **hw_id**                   |   string    |
        +-----------------------------+-------------+
        | **uuf_test**                |    bool     |
        +-----------------------------+-------------+
        | **parameter_1**             |   string    |
        +-----------------------------+-------------+
        | **executed_test_loops**     |   integer   |
        +-----------------------------+-------------+
        """
        BuiltIn().run_keyword("report to rp", name, result, ca, build, **params)
